// Thumbnails in the panel — NO character is ever built here.
//  1. Built-in presets/themes and known accessories: STATIC images from web/thumbs
//     (generated by web/tools/gen-thumbs.html; index at ../thumbs/index.json). Plain <img> URLs.
//  2. Custom (user) outfits: the latest `preview-frame` mirrored from the character window,
//     captured on save/edit and stored on disk via thumb_put (raw WEBP/JPEG bytes, x-key header).
//  3. Unknown/new accessories only: rendered at runtime (one shared small renderer, one per frame,
//     framing box checked for NaN), stored via thumb_put.
import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { buildAccessory, MaterialLib, DIM } from './legacy';
import { emit, invoke, invokeRaw, listen } from './bridge';

export const THUMB_VERSION = 5;
const mem = new Map<string, string>(); // cache id -> URL (static path or object URL)
const keyFor = (id: string) => `thumb_${id}_${THUMB_VERSION}`.toLowerCase().replace(/[^a-z0-9_-]/g, '-').slice(0, 96);
const fileSafe = (id: string) => id.toLowerCase().replace(/[^a-z0-9_-]/g, '-');
const bump = new Set<() => void>();
/** cards re-check their image when a custom thumbnail is captured */
export function onThumbsChanged(cb: () => void) { bump.add(cb); return () => { bump.delete(cb); }; }

/* ------------------------------------------------------------ static index */
type Index = { version: number; items: Record<string, { file: string; hash: string }> };
let indexP: Promise<Index | null> | null = null;
export function staticIndex() {
  indexP ||= fetch('../thumbs/index.json', { cache: 'no-cache' })
    .then((r) => (r.ok ? r.json() : null))
    .catch((e) => { console.error('[thumb] ../thumbs/index.json missing — run the generator (README: npm run thumbs):', e); return null; });
  return indexP;
}
async function staticUrl(kind: 'preset' | 'acc', id: string) {
  const idx = await staticIndex();
  const it = idx?.items?.[`${kind}:${id}`];
  return it ? `../thumbs/${it.file}` : null;
}

/* ------------------------------------------------------------ disk cache */
let cacheBroken = false;
function withTimeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
  return Promise.race([p, new Promise<T>((_, rej) => setTimeout(() => rej(new Error(`${what} timed out after ${ms} ms`)), ms))]);
}
async function cacheGet(id: string, type = 'image/webp'): Promise<string | null> {
  if (cacheBroken) return null;
  try {
    const v: any = await withTimeout(invoke('thumb_get', { key: keyFor(id) }), 3000, 'thumb_get');
    const bytes: any = v instanceof ArrayBuffer ? v : ArrayBuffer.isView(v) ? v : Array.isArray(v) ? new Uint8Array(v) : null;
    if (!bytes || bytes.byteLength === 0) return null; // miss
    return URL.createObjectURL(new Blob([bytes], { type }));
  } catch (e) { console.error('[thumb] cache read failed:', e); cacheBroken = true; return null; }
}
async function cachePut(id: string, blob: Blob) {
  if (cacheBroken) return;
  try { await invokeRaw('thumb_put', new Uint8Array(await blob.arrayBuffer()), { 'x-key': keyFor(id) }); }
  catch (e) { console.error('[thumb] cache write failed:', e); }
}

/* --------------------------------------------- presets: static, custom: mirror */
/** built-in preset/theme -> static image URL, or null (card shows 🚽) */
export async function presetThumb(id: string): Promise<string | null> {
  const k = `preset-${id}`;
  if (mem.has(k)) return mem.get(k)!;
  const u = await staticUrl('preset', id);
  if (u) mem.set(k, u);
  return u;
}
/** user outfit -> captured mirror frame (disk cached), or null */
export async function customThumb(id: string): Promise<string | null> {
  const k = `custom-${fileSafe(id)}`;
  if (mem.has(k)) return mem.get(k)!;
  const u = await cacheGet(k);
  if (u) mem.set(k, u);
  return u;
}
/**
 * Capture the character window as the thumbnail of a user outfit: ask for a fresh frame
 * (preview-snap) and take the next `preview-frame`. The avatar must already wear the outfit.
 */
export function captureCustomThumb(id: string, timeoutMs = 3000): Promise<string | null> {
  const k = `custom-${fileSafe(id)}`;
  return new Promise((resolve) => {
    let un = () => {};
    const timer = setTimeout(() => { un(); console.error(`[thumb] no preview-frame within ${timeoutMs} ms for ${id} (is the character window open?)`); resolve(null); }, timeoutMs);
    un = listen('preview-frame', async (f: any) => {
      if (!f?.data) return;
      clearTimeout(timer); un();
      try {
        const blob = await (await fetch(f.data)).blob();
        const old = mem.get(k);
        if (old?.startsWith('blob:')) URL.revokeObjectURL(old);
        const url = URL.createObjectURL(blob);
        mem.set(k, url);
        cachePut(k, blob);
        bump.forEach((cb) => cb());
        resolve(url);
      } catch (e) { console.error('[thumb] capture failed:', e); resolve(null); }
    });
    emit('preview-snap', {});
  });
}

/* ------------------------------------------- accessories: static, else runtime */
let R: any = null;
let disposeTimer: any = 0;
function ctx() {
  clearTimeout(disposeTimer);
  if (R) return R;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 128;
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, preserveDrawingBuffer: true, powerPreference: 'low-power' });
  renderer.setPixelRatio(1);
  renderer.setSize(128, 128, false);
  renderer.toneMapping = THREE.NeutralToneMapping;
  renderer.setClearColor(0x000000, 0);
  const scene = new THREE.Scene();
  const pm = new THREE.PMREMGenerator(renderer);
  const env = pm.fromScene(new RoomEnvironment(), 0.04).texture;
  pm.dispose();
  scene.environment = env;
  scene.environmentIntensity = 0.9;
  scene.add(new THREE.HemisphereLight(0xffffff, 0x8c8478, 0.6));
  const key = new THREE.DirectionalLight(0xfff0dc, 2.2);
  key.position.set(2, 3, 3);
  const rim = new THREE.DirectionalLight(0xffffff, 0.8);
  rim.position.set(-2, 2, -3);
  scene.add(key, rim);
  R = { renderer, scene, env, camera: new THREE.PerspectiveCamera(30, 1, 0.01, 50) };
  return R;
}
function scheduleDispose() {
  clearTimeout(disposeTimer);
  disposeTimer = setTimeout(() => {
    if (!R || jobs.length || busy) return;
    try { R.env.dispose(); R.renderer.dispose(); R.renderer.forceContextLoss(); } catch { /* already lost */ }
    R = null;
  }, 4000);
}

type Job = { id: string; fn: () => Promise<Blob | null>; res: (v: Blob | null) => void };
const jobs: Job[] = [];
let busy = false, scheduled = false, lastProgress = performance.now();
function schedule() {
  if (scheduled || busy || !jobs.length) return;
  scheduled = true;
  let fired = false;
  const go = () => { if (fired) return; fired = true; scheduled = false; runOne(); };
  requestAnimationFrame(go);
  setTimeout(go, 100); // throttled/hidden windows still progress
}
async function runOne() {
  const j = jobs.shift();
  if (!j) { scheduleDispose(); return; }
  busy = true;
  let blob: Blob | null = null;
  try { blob = await withTimeout(j.fn(), 8000, `render ${j.id}`); }
  catch (e) { console.error(`[thumb] ${j.id} failed:`, e); if (/context|webgl/i.test(String(e))) R = null; }
  busy = false;
  lastProgress = performance.now();
  j.res(blob);
  if (jobs.length) schedule(); else scheduleDispose();
}
setInterval(() => { // watchdog
  if (jobs.length && !busy && !scheduled) schedule();
  if (busy && performance.now() - lastProgress > 12000) { console.error('[thumb] watchdog: job stuck, restarting queue'); busy = false; schedule(); }
}, 1000);
const queue = (id: string, fn: () => Promise<Blob | null>) => new Promise<Blob | null>((res) => { jobs.push({ id, fn, res }); schedule(); });

const NEUTRAL = { dt: 1 / 60, time: 0, mouth: 0, talk: 0, headYawVel: 0, headPitchVel: 0, lift: 0 };
const finiteBox = (b: any) => !b.isEmpty() && [b.min.x, b.min.y, b.min.z, b.max.x, b.max.y, b.max.z].every(Number.isFinite);
async function renderAccessory(id: string, theme: any): Promise<Blob | null> {
  const mats = new MaterialLib(theme?.materials || {});
  let obj: any = null;
  const { renderer, scene, camera } = ctx();
  try {
    obj = buildAccessory({ THREE, mats, theme, dim: DIM }, { id, params: {} });
    if (!obj) throw new Error(`accessory "${id}" built nothing`);
    for (let i = 0; i < 3; i++) obj.traverse((x: any) => x.userData.update?.(NEUTRAL));
    scene.add(obj);
    obj.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(obj);
    if (!finiteBox(box)) throw new Error('framing box is empty/NaN');
    const sphere = box.getBoundingSphere(new THREE.Sphere());
    const d = (sphere.radius / Math.sin(THREE.MathUtils.degToRad(camera.fov / 2))) * 1.05;
    camera.position.copy(sphere.center).add(new THREE.Vector3(0.55, 0.3, 1).normalize().multiplyScalar(d));
    camera.near = d / 50; camera.far = d * 4;
    camera.lookAt(sphere.center);
    camera.updateProjectionMatrix();
    renderer.render(scene, camera);
    const blob = await new Promise<Blob | null>((res) => renderer.domElement.toBlob(res, 'image/webp', 0.85));
    if (!blob || blob.size < 200) throw new Error(`readback too small (${blob?.size ?? 0} bytes)`);
    return blob;
  } finally {
    if (obj) { scene.remove(obj); obj.traverse((m: any) => { if (m.isMesh && !m.userData.keepGeo) m.geometry?.dispose(); }); }
    mats.dispose();
  }
}

const pending = new Map<string, Promise<string | null>>();
/** accessory -> static image if the generator made one, else rendered once at runtime + disk cached */
export function accessoryThumb(id: string, theme: any): Promise<string | null> {
  const k = `acc-${id}`;
  if (mem.has(k)) return Promise.resolve(mem.get(k)!);
  if (pending.has(k)) return pending.get(k)!;
  const p = (async () => {
    const st = await staticUrl('acc', id);
    if (st) { mem.set(k, st); return st; }
    const hit = await cacheGet(k);
    if (hit) { mem.set(k, hit); return hit; }
    const blob = await queue(k, () => renderAccessory(id, theme));
    if (!blob) return null;
    const url = URL.createObjectURL(blob);
    mem.set(k, url);
    cachePut(k, blob);
    return url;
  })().catch((e) => { console.error(`[thumb] ${k}:`, e); return null; }).finally(() => pending.delete(k));
  pending.set(k, p);
  return p;
}

/** forget in-memory URLs (static files and captured customs are re-read; runtime ones re-render) */
export function clearThumbs() {
  for (const u of mem.values()) if (u.startsWith('blob:')) URL.revokeObjectURL(u);
  mem.clear();
  indexP = null;
  bump.forEach((cb) => cb());
}
